<script lang="ts">
 import type{Project,MoneyMode}from '../model';
 import {design,energy,economics,num,price}from '../engine/calculate';
 import LineChart from './LineChart.svelte';
 export let project:Project;export let update:(p:Partial<Project>)=>void;
 $: d=design(project);$: en=energy(project,d);$: ec=economics(project,d,en);
 const n=(ev:Event)=>Number((ev.currentTarget as HTMLInputElement).value);
 function setFin(field:keyof Project['finance'],v:number|string){update({finance:{...project.finance,[field]:v}})}
</script>
<section class="stage-heading"><h1>محاسبات اقتصادی نیروگاه</h1><p>بازده اقتصادی بر اساس قیمت‌های ثبت‌شده، تولید قابل محاسبه و مفروضات بیست‌ساله به‌روز می‌شود.</p></section>
<div class="kpi-row"><div class="kpi"><span>سرمایه‌گذاری اولیه</span><b>{price(ec.capex)}</b></div><div class="kpi"><span>درآمد سال اول</span><b>{ec.ready?price(ec.annualRevenue):'نامشخص'}</b></div><div class="kpi"><span>NPV</span><b>{ec.ready?price(ec.npv):'نامشخص'}</b></div><div class="kpi"><span>IRR</span><b>{ec.ready&&ec.irr!==null?num(ec.irr,2)+'%':'—'}</b></div><div class="kpi"><span>بازگشت ساده</span><b>{ec.ready&&ec.payback!==null?num(ec.payback,2)+' سال':'—'}</b></div><div class="kpi"><span>LCOE</span><b>{ec.ready&&ec.lcoe!==null?num(ec.lcoe,1)+' ریال/kWh':'—'}</b></div></div>
{#if !ec.ready}<div class="message message-warning">تحلیل سرمایه‌گذاری تا تکمیل قیمت پنل، اینورتر، سایر هزینه‌ها، تعرفه معتبر و رفع خطاهای طراحی نهایی نیست. اعداد محاسبه‌نشده به‌جای خروجی ساختگی پنهان شده‌اند.</div>{/if}
<div class="economic-forms"><div class="panel"><h2>مدل درآمد و فروش برق</h2><div class="form-grid"><label>روش ارزیابی<select value={project.finance.mode} onchange={e=>setFin('mode',e.currentTarget.value as MoneyMode)}><option value="FIT">خرید تضمینی</option><option value="GREEN">تابلو سبز</option><option value="MIX">ترکیب دو تعرفه</option><option value="SELF">خودمصرفی بدون فروش</option></select></label><label>تعرفه خرید تضمینی (ریال/kWh)<input type="number" min="0" value={project.finance.tariffFit} oninput={e=>setFin('tariffFit',n(e))}/></label><label>قیمت تابلو سبز (ریال/kWh)<input type="number" min="0" value={project.finance.tariffGreen} oninput={e=>setFin('tariffGreen',n(e))}/></label><label>ارزش برق خودمصرفی (ریال/kWh)<input type="number" min="0" value={project.finance.valueSelf} oninput={e=>setFin('valueSelf',n(e))}/></label><label>سهم تابلو سبز در مدل ترکیبی (%)<input type="number" min="0" max="100" value={project.finance.greenSharePct} oninput={e=>setFin('greenSharePct',n(e))}/></label></div><div class="hint">تعرفه‌ها ورودی کاربر هستند و به سامانه خرید برق یا بورس انرژی متصل نیستند. محدودیت قانونی تزریق باید جداگانه بررسی شود.</div></div>
<div class="panel"><h2>فرضیات مالی ۲۰ ساله</h2><div class="form-grid">{#each [['annualGrowthPct','رشد سالانه تعرفه (%)'],['annualDegradationPct','افت تولید سالانه (%)'],['opexPct','OPEX سالانه (% CAPEX)'],['discountPct','نرخ تنزیل (%)'],['replacementYear','سال تعویض تجهیز'],['replacementPct','هزینه تعویض (% CAPEX)'],['otherCapex','سایر CAPEX (ریال)']] as field}<label>{field[1]}<input type="number" step="0.1" value={project.finance[field[0] as keyof Project['finance']]} oninput={e=>setFin(field[0] as keyof Project['finance'],n(e))}/></label>{/each}</div></div></div>
<div class="layout-two lower-cards"><div class="panel"><div class="panel-head"><h2>جریان نقدی تجمعی ۲۰ سال</h2><span class="chip">ریال</span></div><LineChart values={ec.ready?[-ec.capex,...ec.rows.map(x=>x.cumulative)]:[]} suffix="ریال"/></div><div class="panel"><h2>درآمد دوره‌ای — سال اول</h2>{#if ec.ready}<div class="spec-grid large"><span>ساعتی (میانگین) <b>{price(ec.annualRevenue/8760)}</b></span><span>روزانه (میانگین) <b>{price(ec.annualRevenue/365)}</b></span><span>هفتگی (میانگین) <b>{price(ec.annualRevenue/52)}</b></span><span>ماهانه (میانگین) <b>{price(ec.annualRevenue/12)}</b></span><span>سالانه <b>{price(ec.annualRevenue)}</b></span><span>سال اول خالص <b>{price(ec.annualNet)}</b></span></div>{:else}<p class="muted">پس از تکمیل ورودی‌ها نمایش داده می‌شود.</p>{/if}</div></div>
<div class="panel"><h2>جدول جریان نقدی ۲۰ساله</h2><div class="table-scroll"><table><thead><tr><th>سال</th><th>تولید (kWh)</th><th>درآمد (ریال)</th><th>OPEX و تعویض (ریال)</th><th>خالص (ریال)</th><th>تجمعی (ریال)</th></tr></thead><tbody>{#each ec.ready?ec.rows:[] as row}<tr><td>{num(row.year)}</td><td>{num(row.energy)}</td><td>{num(row.revenue)}</td><td>{num(row.cost)}</td><td>{num(row.net)}</td><td>{num(row.cumulative)}</td></tr>{/each}</tbody></table></div></div>

